


export type ReturnLineDecisionInput = ({ "allowed_resolution_types"?: Array<"refund" | "exchange" | "replacement" | "no_monetary_action">; /** Whole-number quantity; fractional quantities are not supported. Approved quantity ranges from zero through the return line's requested_quantity. Declining any requested quantity requires decline_reason; decline context is invalid when all requested quantity is approved. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "approved_quantity": string; /** Which decision semantics this line uses. With policy_evaluation you accept the recorded policy proposal and send only approved_quantity plus decline context; the explicit fields are rejected. With explicit you state the outcome yourself and return_required_quantity is required, and approving any quantity also requires allowed_resolution_types and resolution_mode. A resolution_mode of automatic additionally requires selected_resolution_type, and any return_required_quantity above 0 additionally requires a receiving_location_id whose Location has a postal address. */ "decision_basis": "policy_evaluation" | "explicit"; "decline_reason"?: "not_eligible" | "quantity_unavailable" | "evidence_missing" | "suspected_abuse" | "merchant_discretion" | "other"; "decline_reason_message"?: string; "is_inspection_required"?: boolean; /** Required when an explicit decision changes a valid policy proposal. Invalid without a policy to override. */ "override_reason"?: "customer_service_exception" | "policy_correction" | "risk_review" | "merchant_discretion" | "other"; "override_reason_message"?: string; "receiving_location_id"?: string; "refund_timing"?: "after_approval" | "after_handoff" | "after_receipt" | "after_inspection" | "manual"; "resolution_mode"?: "automatic" | "manual"; "return_line_item_id": string; /** How much of the approved quantity the buyer must physically send back; fractional quantities are not supported. Set 0 for a returnless refund, where the buyer keeps the merchandise and the Return still settles the money. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "return_required_quantity"?: string; "selected_resolution_type"?: "refund" | "exchange" | "replacement" | "no_monetary_action"; }) & (((({ "decline_reason_message"?: never })) | ({ "decline_reason": unknown; }))) & (((({ "override_reason_message"?: never })) | ({ "override_reason": unknown; }))) & ((({ "decision_basis": "policy_evaluation"; "approved_quantity": unknown; }) & (({ "return_required_quantity"?: never }) & ({ "allowed_resolution_types"?: never }) & ({ "selected_resolution_type"?: never }) & ({ "resolution_mode"?: never }) & ({ "refund_timing"?: never }) & ({ "is_inspection_required"?: never }) & ({ "receiving_location_id"?: never }) & ({ "override_reason"?: never }) & ({ "override_reason_message"?: never }))) | (({ "decision_basis": "explicit"; "approved_quantity": unknown; "return_required_quantity": unknown; }) & ((({ /** maximum: 0. */ "approved_quantity"?: unknown; /** maximum: 0. */ "return_required_quantity"?: unknown; }) | ({ /** minItems: 1. */ "allowed_resolution_types": unknown; /** minimum: 1. */ "approved_quantity"?: unknown; "resolution_mode": unknown; }))) & (((({ "resolution_mode"?: "manual"; }) & ({ "selected_resolution_type"?: never })) | ({ "resolution_mode": "automatic"; "selected_resolution_type": unknown; }))) & ((({ /** minLength: 1. pattern: \S. */ "receiving_location_id": unknown; /** minimum: 1. */ "return_required_quantity"?: unknown; "is_inspection_required": unknown; }) | ({ "is_inspection_required"?: false; "refund_timing"?: "after_approval" | "manual"; /** maximum: 0. */ "return_required_quantity"?: unknown; }))) & (((unknown) | ({ "is_inspection_required": true; })))));
